    private void open(String s){if(s.equals("History")&&!screen.equals("History"))historyLimit=60;screen=s;render();}
    private void reload(){cachedHome=null;store.invalidate();render();}
    private void render(){
        if(loading||isFinishing()||isDestroyed())return;
        long token=store.fastToken();
        if(token==snapshotToken&&screen.equals("Home")&&cachedHome!=null&&cachedHomeKey.equals(homeKey())){pageRoot=cachedHome;setContentView(cachedHome);return;}
        if(token>=0&&token==snapshotToken&&ledgerIndex!=null){renderLoaded();return;}
        loading=true;if(pageRoot!=null)pageRoot.setTag("ledger.loading");if(pageRoot==null){LinearLayout placeholder=Ui.column(this);placeholder.setBackgroundColor(Ui.BG);placeholder.addView(Ui.title(this,"VibeFinancier"));placeholder.addView(new ProgressBar(this));setContentView(placeholder);}
        io.execute(()->{try{List<JSONObject> values=store.entities(false);long loaded=store.resolvedToken();LedgerIndex index=new LedgerIndex(values);JSONObject usage=new JSONObject();for(JSONObject p:values)if(p.optString("entity").equals("transaction")){String category=p.optString("category");usage.put(category,usage.optInt(category)+1);}store.set("category_usage",usage.toString());runOnUiThread(()->{loading=false;if(isFinishing()||isDestroyed())return;snapshot=values;snapshotToken=loaded;ledgerIndex=index;cachedHome=null;renderLoaded();});}catch(Exception e){runOnUiThread(()->{loading=false;if(!isDestroyed())Ui.message(this,"Cannot display ledger",e.getMessage());});}});
    }
