            TextView sync=Ui.text(this,state,10,Ui.MUTED);sync.setPadding(Ui.dp(this,14),Ui.dp(this,3),Ui.dp(this,14),Ui.dp(this,3));sync.setOnClickListener(v->cloudMenu());root.addView(sync);
            body=Ui.column(this);if(Set.of("Home","Reports","History","Account","Category").contains(screen))body.setPadding(0,0,0,0);ScrollView scroll=null;if(screen.equals("Home")){root.addView(body,new LinearLayout.LayoutParams(-1,0,1));}else{scroll=Ui.scroll(this,body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));}setContentView(root);
