    private String screenTitle(){if(screen.equals("Home"))return "VibeFinancier";if(screen.equals("More"))return "Settings";if(screen.equals("Category")){JSONObject p=categoryIndex.get(detailCategory);return p!=null&&p.optString("direction").equals("income")?"Income":"Expenses";}if(screen.equals("Account")){for(JSONObject p:snapshot)if(p.optString("id").equals(detailAccount))return p.optString("account_type").equals("debt")?"Debts":"Accounts";}return screen;}
