    private boolean inCategory(String id,String parent){Set<String> visited=new HashSet<>();while(!id.isEmpty()&&visited.add(id)){if(id.equals(parent))return true;id=categoryIndex.containsKey(id)?categoryIndex.get(id).optString("parent"):"";}return false;}
