    private void accountDetail()throws Exception {
        JSONObject account=null;for(JSONObject p:type("account",true))if(p.optString("id").equals(detailAccount))account=p;if(account==null){body.addView(Ui.text(this,"Account unavailable",18,Ui.INK));return;}JSONObject selected=account;String currency=account.optString("currency");AccountTimeline timeline=ledgerIndex.timeline(detailAccount);
        String shownCurrency=currency;BigDecimal factor=BigDecimal.ONE;JSONObject displayQuote=null;if(store.get("display_base","false").equals("true")&&!currency.equals(store.get("base","RUB"))){for(JSONObject q:type("rate",true))if(q.optString("currency").equals(currency)&&q.optString("base").equals(store.get("base","RUB")))displayQuote=q;if(displayQuote!=null){shownCurrency=store.get("base","RUB");factor=Money.decimal(displayQuote.getString("rate"));}}
        LinearLayout summary=Ui.column(this);summary.setPadding(Ui.dp(this,16),Ui.dp(this,16),Ui.dp(this,16),Ui.dp(this,8));summary.addView(AccountCard.create(this,account,timeline,()->entityForm("account",selected),shownCurrency,factor));body.addView(summary);if(displayQuote!=null)body.addView(Ui.text(this,"Current reference valuation · "+displayQuote.optString("source")+" · "+displayQuote.optString("asof")+"\nOperations below retain their original amounts and currencies.",12,Ui.MUTED));
        LinearLayout shortcuts=new LinearLayout(this);if(!account.optString("account_type").equals("debt")){shortcuts.addView(Ui.button(this,"Expense",()->EntryForm.show(this,"expense",null,detailAccount,"",this::reload,()->{})),new LinearLayout.LayoutParams(0,-2,1));shortcuts.addView(Ui.button(this,"Income",()->EntryForm.show(this,"income",null,detailAccount,"",this::reload,()->{})),new LinearLayout.LayoutParams(0,-2,1));}shortcuts.addView(Ui.button(this,"Transfer",()->EntryForm.show(this,"transfer",null,detailAccount,"",this::reload,()->{})),new LinearLayout.LayoutParams(0,-2,1));body.addView(shortcuts);
        detailControls();HistoryData data=new HistoryData(snapshot,detailOperations(ledgerIndex.operations.getOrDefault(detailAccount,List.of())),detailAccount,"",store.get("base","RUB"));historyRows(data,detailLimit,account.optString("account_type").equals("debt"),true);
    }
    private void resetDetail(){detailFrom="0001-01-01";detailTo="9999-12-31";detailQuery="";detailFilterAccount="";detailLimit=30;}
    private void categoryActions(JSONObject category){resetDetail();detailCategory=category.optString("id");open("Category");}
    private List<JSONObject> detailOperations(List<JSONObject> values){List<JSONObject> result=new ArrayList<>();for(JSONObject p:values){String date=p.optString("time");if(date.length()>=10){date=date.substring(0,10);if(date.compareTo(detailFrom)<0||date.compareTo(detailTo)>0)continue;}else if(!detailFrom.equals("0001-01-01")||!detailTo.equals("9999-12-31"))continue;if(!detailFilterAccount.isEmpty()){boolean found=false;JSONArray legs=p.optJSONArray("postings");if(legs!=null)for(int i=0;i<legs.length();i++)if(legs.optJSONObject(i).optString("account").equals(detailFilterAccount))found=true;if(!found)continue;}if(!detailQuery.isEmpty()&&!(p.optString("note")+" "+label(p.optString("category"))+" "+label(p.optString("account"))).toLowerCase(Locale.ROOT).contains(detailQuery.toLowerCase(Locale.ROOT)))continue;result.add(p);}return result;}
    private void detailControls(){LinearLayout controls=Ui.column(this);controls.setPadding(Ui.dp(this,16),Ui.dp(this,6),Ui.dp(this,16),Ui.dp(this,6));String period=detailFrom.equals("0001-01-01")&&detailTo.equals("9999-12-31")?Strings.t(this,"All history"):detailFrom+" — "+detailTo;TextView filter=Ui.rawText(this,period+(detailFilterAccount.isEmpty()?"":" · "+label(detailFilterAccount))+(detailQuery.isEmpty()?"":" · "+detailQuery)+"  ▾",13,Ui.GREEN);filter.setMinHeight(Ui.dp(this,40));filter.setGravity(Gravity.CENTER_VERTICAL);filter.setOnClickListener(v->detailFilter());controls.addView(filter);body.addView(controls);}
    private void categoryDetail()throws Exception {
        JSONObject category=categoryIndex.get(detailCategory);if(category==null){body.addView(Ui.text(this,"Category unavailable",18,Ui.INK));return;}HistoryData data=new HistoryData(snapshot,detailOperations(ledgerIndex.categoryOperations.getOrDefault(detailCategory,List.of())),detailFilterAccount,detailCategory,store.get("base","RUB"));LinearLayout summary=Ui.column(this);summary.setPadding(Ui.dp(this,16),Ui.dp(this,16),Ui.dp(this,16),Ui.dp(this,8));summary.addView(HistoryViews.categoryCard(this,category,data,()->entityForm("category",category)));body.addView(summary);detailControls();historyRows(data,detailLimit,false,true);
    }
    private void historyRows(HistoryData data,int limit,boolean debt,boolean detail){HistoryViews.list(this,body,data,limit,debt,new HistoryViews.Actions(){public void open(JSONObject p){transactionDetail(p);}public void edit(JSONObject p){editOperation(p);}public void trash(JSONObject p){trashOperation(p);}public void more(){rememberScroll();if(detail)detailLimit+=30;else historyLimit+=60;render();}});}
    private void detailFilter(){LinearLayout box=Ui.column(this);EditText start=Ui.field(this,box,"From (YYYY-MM-DD)",detailFrom,false),end=Ui.field(this,box,"Through (YYYY-MM-DD)",detailTo,false),query=Ui.field(this,box,"Search",detailQuery,false);List<JSONObject> accounts=type("account",true);List<String> names=new ArrayList<>(List.of("All accounts"));names.addAll(Ui.labels(accounts));Spinner account=Ui.spinner(this,box,"Account",names);account.setEnabled(screen.equals("Category"));for(int i=0;i<accounts.size();i++)if(accounts.get(i).optString("id").equals(screen.equals("Account")?detailAccount:detailFilterAccount))account.setSelection(i+1);AlertDialog dialog=new LocalizedDialog(this).setTitle("Filter operations").setView(Ui.scroll(this,box)).setNegativeButton("Cancel",null).setNeutralButton("All history",(d,w)->{resetDetail();render();}).setPositiveButton("Apply",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{LocalDate from=LocalDate.parse(Ui.value(start)),to=LocalDate.parse(Ui.value(end));if(from.isAfter(to))throw new IllegalArgumentException("End date precedes start date.");detailFrom=from.toString();detailTo=to.toString();detailQuery=Ui.value(query);detailFilterAccount=screen.equals("Category")&&account.getSelectedItemPosition()>0?accounts.get(account.getSelectedItemPosition()-1).optString("id"):"";detailLimit=30;dialog.dismiss();render();}catch(Exception e){start.setError(Strings.t(this,e.getMessage()));}}));dialog.show();}
    @Override public void onBackPressed(){if(!screen.equals("Home"))open("Home");else super.onBackPressed();}
    private void dashboardHome()throws Exception {
        if(store.get("sheet","").isEmpty()){
            LinearLayout connection=Ui.card(this,body);connection.addView(Ui.text(this,"Connect your Google table",18,Ui.INK));connection.addView(Ui.text(this,"Sign in, then create a private table or choose a compatible VibeFinancier table. Setup and storage checks run automatically. No scripts are required.",13,Ui.MUTED));
            connection.addView(Ui.button(this,"Create private table",()->google(c->{String id=new SheetSetup(c).create(store);return "Your private table is ready. No history was uploaded.\n"+SheetSetup.url(id);})));
            connection.addView(Ui.button(this,"Choose existing table",this::pickTable));
        }
        String base=store.get("base","RUB");Map<String,BigDecimal> balances=ledgerIndex.balances,categories=new HashMap<>();Map<String,JSONObject> rates=new HashMap<>();for(JSONObject r:type("rate",true))if(r.optString("base").equals(base))rates.put(r.optString("currency"),r);
        BigDecimal assets=BigDecimal.ZERO,income=BigDecimal.ZERO,expense=BigDecimal.ZERO;int missingRates=0;
        for(JSONObject account:type("account",true)){BigDecimal value=balances.getOrDefault(account.optString("id"),BigDecimal.ZERO);if(account.optString("account_type").equals("debt")||account.optBoolean("exclude_from_total"))continue;String currency=account.optString("currency");if(currency.equals(base))assets=assets.add(value);else if(rates.containsKey(currency))assets=assets.add(value.multiply(Money.decimal(rates.get(currency).optString("rate"))));else missingRates++;}
        for(JSONObject p:filtered()){String kind=p.optString("kind");if(!p.optString("base_currency").equals(base)||!p.has("base_amount"))continue;BigDecimal amount=Money.decimal(p.getString("base_amount"));if(kind.equals("income"))income=income.add(amount);if(kind.equals("expense"))expense=expense.add(amount);if(p.has("fee_base")&&(filterAccount.isEmpty()||p.optString("account").equals(filterAccount)))expense=expense.add(Money.decimal(p.getString("fee_base")));if(kind.equals("income")||kind.equals("expense")){String category=p.optString("category");Set<String> visited=new HashSet<>();while(!category.isEmpty()&&visited.add(category)){categories.merge(category,amount,BigDecimal::add);category=categoryIndex.containsKey(category)?categoryIndex.get(category).optString("parent"):"";}}}
        assets=assets.setScale(Money.scale(base),java.math.RoundingMode.HALF_EVEN);final Map<String,BigDecimal> currentBalances=new HashMap<>(balances);List<JSONObject> displayEntities=snapshot;
        if(store.get("display_base","false").equals("true")){displayEntities=new ArrayList<>();for(JSONObject p:snapshot){JSONObject shown=p;if(p.optString("entity").equals("account")&&!p.optString("currency").equals(base)){shown=new JSONObject(p.toString());JSONObject q=rates.get(p.optString("currency"));if(q!=null){currentBalances.put(p.optString("id"),balances.getOrDefault(p.optString("id"),BigDecimal.ZERO).multiply(Money.decimal(q.optString("rate"))).setScale(Money.scale(base),java.math.RoundingMode.HALF_EVEN));shown.put("display_currency",base);}else shown.put("valuation_missing",true);}displayEntities.add(shown);}}
        Dashboard dashboard=new Dashboard(this,displayEntities,currentBalances,categories,base,assets,income,expense,from+" — "+to+(missingRates>0?" · partial valuation":""),new Dashboard.Actions(){
            public void category(JSONObject p){categoryActions(p);}
            public void account(JSONObject p){accountActions(p);}
            public void operation(JSONObject route){EntryForm.show(MainActivity.this,route.optString("kind"),null,route.optString("account"),route.optString("category"),route.optString("to"),MainActivity.this::reload,()->{});}
            public void edit(JSONObject p){entityForm(p.optString("entity"),p);}
            public void add(String group){newEntityKind=group;entityForm(group.equals("account")||group.equals("debt")?"account":"category",null);}
            public void statistics(){open("Insights");}
        });body.addView(dashboard,new LinearLayout.LayoutParams(-1,0,1));
        store.set("widget_balance",Dashboard.format(assets.setScale(Money.scale(base),java.math.RoundingMode.HALF_EVEN),base)+(missingRates>0?" · partial":""));io.execute(()->FinanceWidget.refresh(getApplicationContext()));
    }
    private List<JSONObject> filtered() throws Exception {
        List<JSONObject> list=new ArrayList<>();for(JSONObject p:type("transaction",true)){
            String date=p.optString("time");if(date.length()>=10)date=date.substring(0,10);if(!date.isEmpty()&&(date.compareTo(from)<0||date.compareTo(to)>0))continue;
            if(filterCategory.equals("__fees__")){if(Money.decimal(p.optString("fee_base","0")).signum()==0||!filterAccount.isEmpty()&&!p.optString("account").equals(filterAccount))continue;}else if(filterCategory.equals("__uncategorized__")){if(!p.optString("category").isEmpty())continue;}else if(!filterCategory.isEmpty()&&!inCategory(p.optString("category"),filterCategory))continue;
            if(!filterAccount.isEmpty()){boolean found=false;JSONArray legs=p.optJSONArray("postings");if(legs!=null)for(int i=0;i<legs.length();i++)if(legs.getJSONObject(i).optString("account").equals(filterAccount))found=true;if(!found)continue;}
            if(!search.isEmpty()&&!(p.optString("note")+" "+label(p.optString("category"))+" "+label(p.optString("account"))).toLowerCase(Locale.ROOT).contains(search.toLowerCase(Locale.ROOT)))continue;list.add(p);
        }list.sort((x,y)->y.optString("time").compareTo(x.optString("time")));return list;
    }
