    private void editOperation(JSONObject p){String kind=p.optString("kind");if(List.of("income","expense","transfer","debt").contains(kind))entry(kind.equals("debt")?"transfer":kind,p);else transactionDetail(p);}
    private void rememberScroll(){if(body!=null&&body.getParent() instanceof ScrollView scroll){pendingScrollY=scroll.getScrollY();pendingScrollScreen=screen;}}
    private void trashOperation(JSONObject p){rememberScroll();if(!deleting.add(p.optString("id")))return;io.execute(()->{try{JSONObject copy=new JSONObject(p.toString());copy.put("deleted",true);JSONObject event=store.edit(copy);copy.put("_head",event.getString("event_id"));SyncWorker.enqueue(getApplicationContext());runOnUiThread(()->{completedDeletes.add(p.optString("id"));undoAction=()->restoreOperation(copy);render();});}catch(Exception e){runOnUiThread(()->{deleting.remove(p.optString("id"));if(!isDestroyed())Ui.message(this,"Delete",e.getMessage());});}});}
    private void restoreOperation(JSONObject tombstone){rememberScroll();io.execute(()->{try{JSONObject copy=new JSONObject(tombstone.toString());copy.put("deleted",false);store.edit(copy);SyncWorker.enqueue(getApplicationContext());runOnUiThread(this::render);}catch(Exception e){runOnUiThread(()->Ui.message(this,"Restore",e.getMessage()));}});}
    private void transactionDetail(JSONObject p){
        String[] actions=(p.optString("kind").equals("expense")||p.optString("kind").equals("income"))?new String[]{"Edit","Move to trash","Show all fields"}:(p.optString("kind").equals("transfer")||p.optString("kind").equals("debt"))?new String[]{"Edit","Move to trash","Show all fields"}:new String[]{"Move to trash","Show all fields"};
        new LocalizedDialog(this).setTitle(p.optString("kind")+" · "+p.optString("amount")).setItems(actions,(d,w)->{String a=actions[w];if(a.equals("Edit"))entry((p.optString("kind").equals("debt")||p.optString("kind").equals("transfer"))?"transfer":p.optString("kind"),p);else if(a.equals("Show all fields"))Ui.message(this,"Operation",p.toString());else new LocalizedDialog(this).setTitle("Move operation to trash?").setMessage("You can restore it from More → Trash.").setNegativeButton("Cancel",null).setPositiveButton("Move to trash",(x,y)->{try{p.put("deleted",true);store.edit(p);SyncWorker.enqueue(this);render();}catch(Exception e){Ui.message(this,"Delete",e.getMessage());}}).show();}).show();
    }
    private void insights()throws Exception {
        filterControls();String base=store.get("base","RUB");Map<String,BigDecimal> groups=new LinkedHashMap<>();BigDecimal income=BigDecimal.ZERO,expense=BigDecimal.ZERO;int missing=0;
        body.addView(Ui.button(this,"Save this report to Google Sheets",()->google(c->{c.calculateView(store,from,to,filterAccount,filterCategory);return "The report was calculated on this device and saved to your Google Sheet.";})));
        for(JSONObject p:filtered()){String k=p.optString("kind");if(!k.equals("income")&&!k.equals("expense")&&!p.has("fee_base"))continue;if(!p.optString("base_currency").equals(base)){missing++;continue;}if(k.equals("income"))income=income.add(Money.decimal(p.getString("base_amount")));if(k.equals("expense")){BigDecimal a=Money.decimal(p.getString("base_amount"));expense=expense.add(a);groups.merge(p.optString("category"),a,BigDecimal::add);}if(p.has("fee_base")&&(filterAccount.isEmpty()||p.optString("account").equals(filterAccount)))expense=expense.add(Money.decimal(p.getString("fee_base")));}
        LinearLayout totals=Ui.card(this,body);totals.addView(Ui.text(this,"HISTORICAL RATES · "+base,12,Ui.MUTED));totals.addView(Ui.text(this,"Income  "+Money.plain(income)+"\nExpenses  "+Money.plain(expense)+"\nDifference  "+Money.plain(income.subtract(expense)),22,Ui.GREEN));totals.addView(Ui.text(this,"Calculated on this device. "+"Transfers, debt principal and opening values are excluded."+(missing>0?" "+missing+" entries lack a saved rate for this base currency.":""),12,Ui.MUTED));
        periodComparison(base);monthlyTrend(base);
        body.addView(Ui.text(this,"Expenses by category · tap to inspect",16,Ui.INK));List<Map.Entry<String,BigDecimal>> ordered=new ArrayList<>(groups.entrySet());ordered.sort((x,y)->y.getValue().compareTo(x.getValue()));BigDecimal max=ordered.isEmpty()?BigDecimal.ONE:ordered.get(0).getValue();
        for(Map.Entry<String,BigDecimal> e:ordered){LinearLayout c=Ui.card(this,body);c.addView(Ui.text(this,label(e.getKey())+"  "+Money.plain(e.getValue()),14,Ui.INK));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(10000);bar.setProgress(max.signum()==0?0:e.getValue().multiply(BigDecimal.valueOf(10000)).divide(max,0,java.math.RoundingMode.HALF_EVEN).intValue());c.addView(bar);c.setOnClickListener(v->{filterCategory=e.getKey();open("History");});}
        body.addView(Ui.text(this,"Report snapshot saved at last synchronization",17,Ui.INK));JSONArray cloud=new JSONArray(store.get("cloud_summary","[]"));if(cloud.length()==0)body.addView(Ui.text(this,"Connect and synchronize a table to save a report snapshot.",13,Ui.MUTED));else for(int i=0;i<Math.min(cloud.length(),40);i++)body.addView(Ui.text(this,cloud.getJSONArray(i).join(" · "),12,Ui.MUTED));
    }
    private void entityForm(String type,JSONObject old){
        if(type.equals("account")){try{String initial=newEntityKind.isEmpty()?"cash":newEntityKind;newEntityKind="";AccountForm.show(this,store,snapshot,old,initial,this::render);}catch(Exception e){Ui.message(this,"Account",e.getMessage());}return;}
        try{LinearLayout box=Ui.column(this);EditText name=Ui.field(this,box,"Name",old==null?"":old.optString("name"),false);EditText currency=type.equals("account")?Ui.field(this,box,"Currency (ISO code, USDT, TON, BTC or ETH)",old==null?store.get("base","RUB"):old.optString("currency"),false):null;
            List<String> kinds=type.equals("account")?List.of("cash","bank_card","savings","crypto","debt","other"):List.of("expense","income");Spinner kind=Ui.spinner(this,box,type.equals("account")?"Account type":"Direction",kinds);if(old==null&&!newEntityKind.isEmpty()){kind.setSelection(Math.max(0,kinds.indexOf(newEntityKind)));newEntityKind="";}if(old!=null)kind.setSelection(Math.max(0,kinds.indexOf(old.optString(type.equals("account")?"account_type":"direction"))));
            IconPicker icon=new IconPicker(this,old==null?"cart":IconCatalog.resolve(old),old==null?IconCatalog.COLORS[0]:IconCatalog.color(old));box.addView(icon);List<JSONObject> parents=type.equals("category")?type("category",false):List.of();List<String> names=new ArrayList<>(List.of("No parent"));names.addAll(Ui.labels(parents));Spinner parent=type.equals("category")?Ui.spinner(this,box,"Parent category",names):null;if(old!=null&&parent!=null)for(int i=0;i<parents.size();i++)if(parents.get(i).optString("id").equals(old.optString("parent")))parent.setSelection(i+1);
            EditText opening=type.equals("account")&&old==null?Ui.field(this,box,"Signed opening balance (optional)","0",true):null;
            CheckBox archived=new CheckBox(this);archived.setText(Strings.t(this,"Archived (history is preserved)"));archived.setChecked(old!=null&&old.optBoolean("archived"));box.addView(archived);
            AlertDialog dialog=new LocalizedDialog(this).setTitle((old==null?"New ":"Edit ")+type).setView(Ui.scroll(this,box)).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{if(Ui.value(name).isEmpty())throw new IllegalArgumentException("Enter a name.");JSONObject p=old==null?Ledger.obj("id",UUID.randomUUID().toString(),"entity",type):new JSONObject(old.toString());p.put("name",Ui.value(name));p.put("icon",icon.icon());if(icon.svg().isEmpty())p.remove("icon_svg");else p.put("icon_svg",icon.svg());p.put("color",icon.color());p.put("archived",archived.isChecked());
                if(type.equals("account")){String cur=Ui.value(currency).toUpperCase(Locale.ROOT);Money.scale(cur);if(old!=null&&!cur.equals(old.optString("currency")))throw new IllegalArgumentException("Create a new account to use another currency; history keeps its original currency.");p.put("currency",cur);p.put("account_type",kinds.get(kind.getSelectedItemPosition()));}
                else{p.put("direction",kinds.get(kind.getSelectedItemPosition()));String par=parent.getSelectedItemPosition()==0?"":parents.get(parent.getSelectedItemPosition()-1).optString("id");if(par.equals(p.getString("id"))||inCategory(par,p.getString("id")))throw new IllegalArgumentException("A category cannot be its own parent.");if(!par.isEmpty()&&!parents.get(parent.getSelectedItemPosition()-1).optString("direction").equals(p.optString("direction")))throw new IllegalArgumentException("Parent direction must match.");p.put("parent",par);}
                if(opening!=null){String value=Money.plain(Money.decimal(Ui.value(opening).replace(',','.')));String abs=Money.input(Money.decimal(value).abs().toPlainString(),p.getString("currency"));String head=p.optString("_head");p.remove("_head");List<JSONObject> events=new ArrayList<>();events.add(Ledger.event(p,head,UUID.randomUUID().toString()));if(Money.decimal(abs).signum()!=0){JSONObject op=Ledger.obj("id",UUID.randomUUID().toString(),"entity","transaction","kind","opening","amount",value,"currency",p.getString("currency"),"note","Initial balance","time",LocalDateTime.now().withNano(0).toString(),"postings",new JSONArray().put(Ledger.obj("account",p.getString("id"),"currency",p.getString("currency"),"amount",value)));events.add(Ledger.event(op,"",UUID.randomUUID().toString()));}store.merge(events,true);}else{List<JSONObject> values=categoryMetadata();for(int i=0;i<values.size();i++)if(values.get(i).optString("id").equals(p.optString("id")))values.set(i,p);if(old==null){values.add(p);}store.merge(EntityHierarchy.move(p,p.optString("parent"),p.optString("direction"),values),true);}
                SyncWorker.enqueue(this);dialog.dismiss();render();}catch(Exception e){name.setError(e.getMessage());}}));dialog.show();
        }catch(Exception e){Ui.message(this,"Edit",e.getMessage());}
    }
    private BigDecimal netFor(List<JSONObject> transactions,String start,String end,String base){
        BigDecimal net=BigDecimal.ZERO;
        for(JSONObject p:transactions){String date=p.optString("time");if(date.length()<10)continue;date=date.substring(0,10);if(date.compareTo(start)<0||date.compareTo(end)>0||!p.optString("base_currency").equals(base))continue;
            if(!filterAccount.isEmpty()){boolean found=false;JSONArray legs=p.optJSONArray("postings");if(legs!=null)for(int i=0;i<legs.length();i++)if(legs.optJSONObject(i).optString("account").equals(filterAccount))found=true;if(!found)continue;}
            if(filterCategory.equals("__fees__")){if(Money.decimal(p.optString("fee_base","0")).signum()==0||!filterAccount.isEmpty()&&!p.optString("account").equals(filterAccount))continue;}else if(filterCategory.equals("__uncategorized__")){if(!p.optString("category").isEmpty())continue;}else if(!filterCategory.isEmpty()&&!inCategory(p.optString("category"),filterCategory))continue;
            if(p.optString("kind").equals("income"))net=net.add(Money.decimal(p.optString("base_amount","0")));
            if(p.optString("kind").equals("expense"))net=net.subtract(Money.decimal(p.optString("base_amount","0")));
            if(p.has("fee_base")&&(filterAccount.isEmpty()||p.optString("account").equals(filterAccount)))net=net.subtract(Money.decimal(p.optString("fee_base")));
        }return net;
    }
    private void periodComparison(String base){
        try{LocalDate start=LocalDate.parse(from),end=LocalDate.parse(to);long days=java.time.temporal.ChronoUnit.DAYS.between(start,end)+1;if(days<=0||days>3660)return;LocalDate previousEnd=start.minusDays(1),previousStart=previousEnd.minusDays(days-1);BigDecimal current=netFor(type("transaction",true),from,to,base),previous=netFor(type("transaction",true),previousStart.toString(),previousEnd.toString(),base);LinearLayout c=Ui.card(this,body);c.addView(Ui.text(this,"Previous "+days+" days",15,Ui.INK));c.addView(Ui.text(this,previousStart+" — "+previousEnd+"\nNet "+Money.plain(previous)+" "+base+" · change "+Money.plain(current.subtract(previous)),13,Ui.MUTED));c.setOnClickListener(v->{from=previousStart.toString();to=previousEnd.toString();render();});}catch(DateTimeException ignored){}
    }
    private void monthlyTrend(String base)throws Exception {
        TreeMap<String,BigDecimal> months=new TreeMap<>();for(JSONObject p:filtered()){String time=p.optString("time");if(time.length()<7||!p.optString("base_currency").equals(base))continue;String kind=p.optString("kind");BigDecimal amount=kind.equals("income")?Money.decimal(p.optString("base_amount","0")):kind.equals("expense")?Money.decimal(p.optString("base_amount","0")).negate():BigDecimal.ZERO;if(p.has("fee_base")&&(filterAccount.isEmpty()||p.optString("account").equals(filterAccount)))amount=amount.subtract(Money.decimal(p.optString("fee_base")));months.merge(time.substring(0,7),amount,BigDecimal::add);}
        if(months.isEmpty())return;body.addView(Ui.text(this,"Monthly net movement · calculated on device",16,Ui.INK));BigDecimal max=BigDecimal.ONE;for(BigDecimal amount:months.values())if(amount.abs().compareTo(max)>0)max=amount.abs();
        for(var entry:months.entrySet()){LinearLayout c=Ui.card(this,body);c.addView(Ui.text(this,entry.getKey()+"  "+Money.plain(entry.getValue())+" "+base,13,Ui.INK));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(10000);bar.setProgress(entry.getValue().abs().multiply(BigDecimal.valueOf(10000)).divide(max,0,java.math.RoundingMode.HALF_EVEN).intValue());bar.setProgressTintList(android.content.res.ColorStateList.valueOf(entry.getValue().signum()<0?0xffb65542:Ui.GREEN));c.addView(bar);c.setOnClickListener(v->{YearMonth month=YearMonth.parse(entry.getKey());from=month.atDay(1).toString();to=month.atEndOfMonth().toString();open("History");});}
    }
